/* Connect authored water to the existing scene, without a second Three runtime. */
window.createVillageWater=async({T,scene,world,renderer,sun,hemi,ambient,depth,objects,state,mist})=>{
 const pond=await window.createWaterPond({assetBase:'assets/painterly-water/',size:190,segments:128,objectCount:112});
 // Screenshot preset; object scale is 2/3 of the previous in-game scale.
 Object.assign(pond.settings,{speed:2,wave:2,bottomIntensity:1.05,detailIntensity:1,reflectionIntensity:1.25,reflectionScale:.8,objectCount:112,objectScale:1/1.5,randomness:.45,rippleIntensity:.55,surfaceOpacity:.7,blur:.8,normalStrength:2,lightAngle:2.1,shadowStrength:1});
 pond.group.position.y=-1.22;pond.group.userData.navigationIgnore=pond.group.userData.outlineIgnore=true;
 pond.group.traverse(o=>{o.userData.navigationIgnore=o.userData.outlineIgnore=true;o.raycast=()=>{};if(o.isMesh)o.renderOrder+=2});world.add(pond.group);
 const probes=[[-10,1,-24],[-14,1,8]].map(position=>{const targets=[0,1].map(()=>new T.WebGLCubeRenderTarget(96,{generateMipmaps:true,minFilter:T.LinearMipmapLinearFilter,encoding:T.sRGBEncoding}));const camera=new T.CubeCamera(.2,220,targets[0]);camera.position.set(...position);scene.add(camera);return {targets,camera,current:0,blend:1,ready:false}});
 const canvas=document.createElement('canvas');canvas.width=canvas.height=512;const ctx=canvas.getContext('2d'),shadow=new T.CanvasTexture(canvas);shadow.wrapS=shadow.wrapT=T.ClampToEdgeWrapping;pond.setShadowTexture(shadow);
 let lastReflection=-Infinity,lastShadow=-Infinity,nextProbe=0,lastMode=null,capture=null;
 const materials=[...new Set([...pond.layers.map(l=>l.mesh.material),pond.surface.material,...pond.ripples.map(r=>r.material),...pond.objectBatches.map(o=>o.material)])];
 for(const m of materials)mist?.(m,'vWaterWorld');
 function shadows(){ctx.fillStyle='white';ctx.fillRect(0,0,512,512);const shiftX=-sun.position.x/35,shiftZ=-sun.position.z/35;for(const object of objects()){if(!object.parent||object.visible===false)continue;const box=new T.Box3().setFromObject(object),size=box.getSize(new T.Vector3()),p=box.getCenter(new T.Vector3());if(size.y<.5)continue;const x=(p.x+shiftX*size.y*.7+95)/190*512,z=(95-p.z-shiftZ*size.y*.7)/190*512,rx=Math.max(3,(size.x+size.y*.4)/190*256),rz=Math.max(3,(size.z+size.y*.4)/190*256);ctx.save();ctx.translate(x,z);ctx.scale(rx,rz);const gradient=ctx.createRadialGradient(0,0,0,0,0,1);gradient.addColorStop(0,'rgba(0,0,0,.65)');gradient.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=gradient;ctx.fillRect(-1,-1,2,2);ctx.restore()}shadow.needsUpdate=true}
 return {update(dt,time,quality,forest){
  pond.update(dt);
  const tint=hemi.color.clone().multiplyScalar(hemi.intensity*.55).add(ambient.color.clone().multiplyScalar(ambient.intensity)).add(sun.color.clone().multiplyScalar(sun.intensity*.25));
  const lamps=[];scene.traverse(o=>{if(o.isPointLight&&o.intensity>0){let visible=true;for(let p=o;p;p=p.parent)if(!p.visible)visible=false;if(visible)lamps.push(o)}});lamps.sort((a,b)=>b.intensity-a.intensity);const fireflyLights=lamps.filter(l=>l.userData.firefly).slice(0,4),regularLights=lamps.filter(l=>!l.userData.firefly);lamps.splice(0,lamps.length,...regularLights.slice(0,4),...fireflyLights);
  for(const m of materials){const u=m.uniforms;if(sun.shadow.map){u.uSceneShadow.value=sun.shadow.map.texture;u.uSceneShadowMatrix.value.copy(sun.shadow.matrix);u.uHasSceneShadow.value=1;u.uSceneShadowBias.value=sun.shadow.bias;u.uSceneShadowTexel.value.set(1/sun.shadow.mapSize.x,1/sun.shadow.mapSize.y)}u.uAtmosphere.value.copy(tint);u.uLight.value.copy(sun.position).normalize();for(let i=0;i<8;i++){const l=lamps[i];if(l){const p=l.getWorldPosition(new T.Vector3());u.uLamps.value[i].set(p.x,p.y,p.z,l.distance||15);u.uLampColors.value[i].copy(l.color).multiplyScalar(l.intensity)}else{u.uLamps.value[i].set(0,0,0,0);u.uLampColors.value[i].setRGB(0,0,0)}}}
  if(time-lastShadow>3){shadows();lastShadow=time}
  const mode=state().ui.sceneTime;if(mode!==lastMode){lastMode=mode;lastReflection=-Infinity}
  for(const p of probes)p.blend=Math.min(1,p.blend+dt/.8);
  if(!capture&&time-lastReflection>(quality?.reflection||1.3)){const p=probes[nextProbe];if(p.blend>=1){capture={p,slot:p.ready?1-p.current:0,face:0};p.camera.updateMatrixWorld(true)}}
  if(capture){const {p,slot,face}=capture,target=p.targets[slot],visible=pond.group.visible,oldTarget=renderer.getRenderTarget(),oldFace=renderer.getActiveCubeFace(),oldMip=renderer.getActiveMipmapLevel(),oldXR=renderer.xr.enabled,oldShadow=renderer.shadowMap.autoUpdate,oldMipmaps=target.texture.generateMipmaps;pond.group.visible=false;renderer.xr.enabled=false;renderer.shadowMap.autoUpdate=false;target.texture.generateMipmaps=face===5;const restoreForest=forest?.reflectionVisibility?.(p.camera.children[face]);try{renderer.setRenderTarget(target,face);renderer.render(scene,p.camera.children[face]);}finally{restoreForest?.();target.texture.generateMipmaps=oldMipmaps;renderer.setRenderTarget(oldTarget,oldFace,oldMip);renderer.xr.enabled=oldXR;renderer.shadowMap.autoUpdate=oldShadow;pond.group.visible=visible}capture.face++;if(capture.face===6){p.current=slot;p.blend=p.ready?0:1;p.ready=true;nextProbe=1-nextProbe;lastReflection=time;capture=null}}
  for(const m of materials){const u=m.uniforms,a=probes[0],b=probes[1];u.uEnvironment.value=a.targets[a.ready&&a.blend<1?1-a.current:a.current].texture;u.uEnvironmentNext.value=a.targets[a.current].texture;u.uRiverEnvironment.value=(b.ready?b:a).targets[(b.ready?b:a).blend<1?1-(b.ready?b:a).current:(b.ready?b:a).current].texture;u.uRiverEnvironmentNext.value=(b.ready?b:a).targets[(b.ready?b:a).current].texture;u.uReflectionBlend.value.set(a.blend,b.ready?b.blend:a.blend)}
 },dispose(){world.remove(pond.group);for(const p of probes){scene.remove(p.camera);for(const t of p.targets)t.dispose()}pond.dispose();shadow.dispose()}};
};
